std::vector<double> result(2 * dim - 1);
if (result.empty()) {
    return result;
}
result[0] = 1.0; // H_0(x) = 1
if (result.size() == 1) {
    return result;
}
result[1] = 2 * x; // H_1(x) = 2x

for (size_t l = 2; l < result.size(); ++l) {
    result[l] = 2 * x * result[l - 1] - 2.0 * (l - 1) * result[l - 2];
}
return result;

